package com.library.stocktake;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.library.dto.LocationContracts.AddressRow;
import org.springframework.dao.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.*;
import org.springframework.transaction.support.TransactionTemplate;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.function.*;
import static com.library.stocktake.StocktakeSupport.*;

@Service
public class StocktakeService {
    final JdbcTemplate jdbc; final StocktakeProjection projection; final PlatformTransactionManager transactions;
    public StocktakeService(JdbcTemplate j,StocktakeProjection p,PlatformTransactionManager t){jdbc=new StocktakeJdbcTemplate(Objects.requireNonNull(j.getDataSource()));projection=p;transactions=t;}
    public record Actor(long id,boolean admin,boolean librarian) {public void role(){if(!admin&&!librarian)throw fail(403,"STOCKTAKE_ROLE_REQUIRED");}void administrator(){role();if(!admin)throw fail(403,"STOCKTAKE_ROLE_REQUIRED");}}
    <T>T transaction(boolean atomic,boolean read,Supplier<T> body){TransactionTemplate t=new TransactionTemplate(transactions);t.setIsolationLevel(atomic?TransactionDefinition.ISOLATION_READ_COMMITTED:TransactionDefinition.ISOLATION_REPEATABLE_READ);t.setTimeout(15);t.setReadOnly(read);try{return t.execute(s->body.get());}catch(DataAccessException e){Throwable x=e;while(x!=null){if(x instanceof java.sql.SQLException q&&(q.getErrorCode()==3572||q.getErrorCode()==1205||q.getErrorCode()==1213||"40001".equals(q.getSQLState())||q.getErrorCode()==50200))throw fail("STOCKTAKE_BUSY");x=x.getCause();}if(e instanceof QueryTimeoutException||e instanceof PessimisticLockingFailureException)throw fail("STOCKTAKE_BUSY");throw fail(500,"STOCKTAKE_SAVE_FAILED");}catch(TransactionTimedOutException e){throw fail("STOCKTAKE_BUSY");}}
    Map<String,Object> sessionRow(long id,boolean lock){List<Map<String,Object>>r=jdbc.queryForList("SELECT * FROM stocktake_session WHERE id=?"+(lock?" FOR UPDATE NOWAIT":""),id);if(r.isEmpty())throw fail(404,"STOCKTAKE_NOT_FOUND");return r.get(0);}
    void access(Map<String,Object>s,Actor actor,boolean edit){actor.role();if(actor.admin)return;if(edit||!"FINALIZED".equals(s.get("state")))if(num(s.get("owner_id"))!=actor.id)throw fail(403,"OWNER_REQUIRED");}
    public JsonNode session(Map<String,Object>s){return obj("sessionId",s.get("id"),"ownerId",s.get("owner_id"),"campaignKey",s.get("campaign_key"),"scope",read((String)s.get("scope_json")),"state",s.get("state"),"revision",s.get("revision"),"baselineSnapshotId",s.get("baseline_snapshot_id"),"finalSnapshotId",s.get("final_snapshot_id"),"createdAt",time(s.get("created_at")),"confirmedAt",time(s.get("confirmed_at")),"receipt",s.get("final_receipt_json")==null?null:read((String)s.get("final_receipt_json")));}
    public JsonNode get(long id,Actor a){a.role();return transaction(false,true,()->{var s=sessionRow(id,false);access(s,a,false);return session(s);});}
    public JsonNode sessions(int page,int size,String state,String campaign,Actor a){a.role();if(state!=null&&!List.of("DRAFT","FINALIZED","CANCELLED").contains(state))invalid();if(campaign!=null&&campaign.length()>100)invalid();return transaction(false,true,()->{List<Object>args=new ArrayList<>();String w=" WHERE 1=1";if(!a.admin){w+=" AND (owner_id=? OR state='FINALIZED')";args.add(a.id);}if(state!=null){w+=" AND state=?";args.add(state);}if(campaign!=null){w+=" AND campaign_key=?";args.add(campaign);}long count=jdbc.queryForObject("SELECT COUNT(*) FROM stocktake_session"+w,Long.class,args.toArray());int p=Math.max(1,page),n=Math.max(1,Math.min(100,size));args.add(n);args.add(((long)p-1)*n);List<JsonNode>r=jdbc.queryForList("SELECT * FROM stocktake_session"+w+" ORDER BY id DESC LIMIT ? OFFSET ?",args.toArray()).stream().map(this::session).toList();return page(r,count,p,n);});}
    static JsonNode page(List<? extends JsonNode>records,long total,int page,int size){return obj("records",records,"total",total,"page",page,"size",size,"pages",total==0?0:(total+size-1)/size);}
    JsonNode slice(List<? extends JsonNode>a,int p,int size){int page=Math.max(1,p),n=Math.max(1,Math.min(100,size));long offset=((long)page-1)*n;return page(a.subList((int)Math.min(offset,a.size()),(int)Math.min(offset+n,a.size())),a.size(),page,n);}
    public JsonNode byKey(String key,Actor actor){actor.role();String k=StocktakeSupport.key(tree(key));return transaction(false,true,()->{List<Map<String,Object>>r=jdbc.queryForList("SELECT * FROM stocktake_operation WHERE operation_key=?",bytes(k));if(r.isEmpty()||r.get(0).get("success_receipt_json")==null)throw fail(404,"OPERATION_NOT_FOUND");var o=r.get(0);if(num(o.get("actor_id"))!=actor.id&&!actor.admin)throw fail(403,"OWNER_REQUIRED");access(sessionRow(num(o.get("session_id")),false),actor,false);if(List.of("CONFIRM","RESOLVE","LINK","REVOKE").contains(o.get("operation")))actor.administrator();return read((String)o.get("success_receipt_json"));});}
    interface Work{JsonNode apply(long operation,Map<String,Object>s,JsonNode input);}
    JsonNode run(String operation,Long id,JsonNode raw,Actor actor,boolean atomic,Work work){return run(operation,id,raw,actor,atomic,null,work);}
    JsonNode run(String operation,Long id,JsonNode raw,Actor actor,boolean atomic,String resource,Work work){actor.role();if(List.of("CONFIRM","RESOLVE","LINK","REVOKE").contains(operation))actor.administrator();JsonNode input=validate(operation,raw);return transaction(atomic,false,()->{if(atomic)lock("inventory_mutex",1);String key=input.path("operationKey").asText(),inputHash=hash(obj("operation",operation,"sessionId",id,"resource",resource,"input",input));
        // Reservation and receipt commit together. A failed attempt leaves no committed key row.
        jdbc.update("INSERT INTO stocktake_operation(operation_key,actor_id,operation,session_id,input_hash,request_json) VALUES (?,?,?,?,?,?) ON DUPLICATE KEY UPDATE id=id",bytes(key),actor.id,operation,id,inputHash,write(input));var o=jdbc.queryForMap("SELECT * FROM stocktake_operation WHERE operation_key=? FOR UPDATE NOWAIT",bytes(key));if(num(o.get("actor_id"))!=actor.id||!operation.equals(o.get("operation"))||!inputHash.equals(o.get("input_hash"))||id!=null&&!Objects.equals(id,nullable(o.get("session_id"))))throw fail("IDEMPOTENCY_KEY_REUSED");Map<String,Object>s=id==null?null:sessionRow(id,true);if(s!=null)access(s,actor,!List.of("RESOLVE","LINK","REVOKE").contains(operation));if(o.get("success_receipt_json")!=null){if(s==null)access(sessionRow(num(o.get("session_id")),false),actor,false);return read((String)o.get("success_receipt_json"));}
        if(s!=null&&!List.of("RESOLVE","LINK","REVOKE").contains(operation)){if(!"DRAFT".equals(s.get("state")))throw fail("FINALIZED".equals(s.get("state"))?"ALREADY_FINALIZED":"REVISION_CONFLICT");if(input.has("expectedRevision")&&num(s.get("revision"))!=input.path("expectedRevision").asLong())throw fail("REVISION_CONFLICT");}
        JsonNode result=work.apply(num(o.get("id")),s,input);long sessionId=id==null?result.path("session").path("sessionId").asLong():id;var updated=sessionRow(sessionId,false);JsonNode receipt=obj("schemaVersion",1,"operationKey",key,"operation",operation,"sessionId",sessionId,"revision",updated.get("revision"),"result",result);int n=jdbc.update("UPDATE stocktake_operation SET session_id=?,success_receipt_json=?,committed_at=? WHERE id=? AND success_receipt_json IS NULL",sessionId,write(receipt),local(now()),o.get("id"));if(n!=1)throw fail(500,"STOCKTAKE_SAVE_FAILED");return read(write(receipt));});}
    JsonNode result(JsonNode session,List<Long>obs,JsonNode review,JsonNode receipt,JsonNode resolution){return obj("session",session,"observationIds",obs,"review",review,"receipt",receipt,"resolution",resolution);}
    void lock(String table,long id){jdbc.queryForList("SELECT id FROM "+table+" WHERE id=? FOR UPDATE NOWAIT",id);}
    void revision(long id,Map<String,Object>s){long r=num(s.get("revision"));if(r==Long.MAX_VALUE)throw fail("REVISION_CONFLICT");if(jdbc.update("UPDATE stocktake_session SET revision=revision+1 WHERE id=? AND revision=?",id,r)!=1)throw fail("REVISION_CONFLICT");s.put("revision",r+1);}
    JsonNode baseline(Map<String,Object>s){return projection.snapshot(num(s.get("id")),num(s.get("baseline_snapshot_id"))).path("graph");}
    JsonNode graph(Map<String,Object>s,List<JsonNode>obs,List<JsonNode>extra){return projection.capture(num(s.get("id")),read((String)s.get("scope_json")),baseline(s),obs,extra);}
    public JsonNode create(JsonNode raw,Actor a){return run("CREATE",null,raw,a,false,(op,s,in)->{JsonNode scope=in.path("scope");if(scope.path("kind").asText().equals("ADDRESS_SET")){Set<Long> ids=longs(scope.path("locationIds"));if(projection.addresses.find(ids).size()!=ids.size())invalid();}JsonNode graph=projection.capture(0,scope,NullNode.instance,List.of(),List.of());if(scope.path("kind").asText().equals("ADDRESS_SET")&&graph.path("addresses").size()!=scope.path("locationIds").size())invalid();String time=now();long id=insert(jdbc,"INSERT INTO stocktake_session(owner_id,campaign_key,scope_json,state,revision,created_at) VALUES (?,?,?,'DRAFT',0,?)",a.id,in.path("campaignKey").isNull()?null:in.path("campaignKey").asText(),write(scope),local(time));var row=sessionRow(id,false);JsonNode review=saveReview(row,a,"BASELINE",null,graph,List.of(),List.of(),projection.coverage(scope,List.of()));jdbc.update("UPDATE stocktake_session SET baseline_snapshot_id=? WHERE id=?",review.path("snapshotId").asLong(),id);return result(session(sessionRow(id,false)),List.of(),review,null,null);});}
    public JsonNode observe(long id,JsonNode raw,Actor a){return run("OBSERVE",id,raw,a,false,(op,s,in)->{List<JsonNode>obs=projection.observations(id);List<JsonNode>newEvents=new ArrayList<>();List<Long>ids=new ArrayList<>();List<Object>eventArgs=new ArrayList<>();eventArgs.add(id);for(JsonNode e:in.path("events"))eventArgs.add(bytes(key(e.get("clientEventKey"))));Map<String,Map<String,Object>>existing=new HashMap<>();for(var r:jdbc.queryForList("SELECT id,client_event_key,input_hash FROM stocktake_observation WHERE session_id=? AND client_event_key IN ("+String.join(",",Collections.nCopies(in.path("events").size(),"?"))+")",eventArgs.toArray()))existing.put(StocktakeSupport.raw(r.get("client_event_key")),r);for(JsonNode e:in.path("events")){String key=key(e.get("clientEventKey"));var old=existing.get(key);if(old!=null){if(!hash(e).equals(old.get("input_hash")))throw fail("IDEMPOTENCY_KEY_REUSED");ids.add(num(old.get("id")));}else newEvents.add(e);}if(!newEvents.isEmpty()){JsonNode g=graph(s,obs,newEvents);for(JsonNode e:newEvents)ids.add(saveObservation(id,"SCAN",key(e.get("clientEventKey")),hash(e),e,g.path("entities"),null,a,in.path("reason").asText(),g));revision(id,s);}return result(session(s),ids,null,null,null);});}
    long saveObservation(long id,String kind,String key,String hash,JsonNode event,JsonNode entities,Long ref,Actor actor,String reason,JsonNode graph){String raw=event==null?null:event.path("rawBarcode").asText();Long copy=null;if(raw!=null)for(JsonNode m:graph.path("barcodeMappings"))if(m.path("rawBarcodeBase64").asText().equals(b64(raw))&&m.path("copyId").isIntegralNumber())copy=m.path("copyId").asLong();return insert(jdbc,"INSERT INTO stocktake_observation(session_id,client_event_key,input_hash,kind,raw_barcode,observed_placement_json,resolved_copy_id_at_scan,signature_json,referenced_observation_id,actor_id,accepted_at,client_observed_at,reason) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",id,bytes(key),hash,kind,bytes(raw),event==null?null:write(projection.observed(event.path("observedPlacement"),graph)),copy,write(kind.equals("VOID")?obj():obj("entities",entities)),ref,actor.id,local(now()),event==null||event.path("clientObservedAt").isNull()?null:local(event.path("clientObservedAt").asText()),reason);}
    public JsonNode correct(long id,JsonNode raw,Actor a){return run("CORRECT",id,raw,a,false,(op,s,in)->{List<JsonNode>obs=projection.observations(id);long ref=in.path("observationId").asLong();JsonNode target=obs.stream().filter(o->o.path("observationId").asLong()==ref).findFirst().orElseThrow(()->fail(404,"STOCKTAKE_NOT_FOUND"));if(!target.path("active").asBoolean()||!List.of("SCAN","CORRECTION").contains(target.path("kind").asText()))throw fail("REVISION_CONFLICT");JsonNode e=in.path("replacement");JsonNode g=graph(s,obs,e.isNull()?List.of():List.of(e));long oid=saveObservation(id,in.path("kind").asText(),null,null,e.isNull()?null:e,g.path("entities"),ref,a,in.path("reason").asText(),g);revision(id,s);return result(session(s),List.of(oid),null,null,null);});}
    long fact(long id,String kind,JsonNode signature,Actor a,String reason){return insert(jdbc,"INSERT INTO stocktake_observation(session_id,kind,signature_json,actor_id,accepted_at,reason) VALUES (?,?,?,?,?,?)",id,kind,write(signature),a.id,local(now()),reason);}
    public JsonNode coverage(long id,JsonNode raw,Actor a){return run("COVERAGE",id,raw,a,false,(op,s,in)->{JsonNode scope=read((String)s.get("scope_json"));Set<Long>allowed=longs(scope.get(scope.path("kind").asText().equals("COPY_SET")?"copyIds":"locationIds"));for(JsonNode i:in.path("items"))if(!allowed.contains(i.path("scopeItemId").asLong()))invalid();long oid=fact(id,"COVERAGE",obj("items",in.path("items")),a,in.path("reason").asText());revision(id,s);return result(session(s),List.of(oid),null,null,null);});}
    public JsonNode check(long id,JsonNode raw,Actor a,boolean prepare){String op=prepare?"PREPARE":"CHECK";return run(op,id,raw,a,false,(oid,s,in)->{List<JsonNode>obs=projection.observations(id);JsonNode g=graph(s,obs,List.of());List<JsonNode>changes=projection.changes(id,num(s.get("revision")),g,projection.references(baseline(s),obs));List<JsonNode>coverage=projection.coverage(g.path("scope"),obs);JsonNode review=saveReview(s,a,op,prepare?in.path("completionKind").asText():null,g,obs,changes,coverage);return result(session(s),List.of(),review,null,null);});}
    JsonNode saveReview(Map<String,Object>s,Actor a,String purpose,String completion,JsonNode graph,List<JsonNode>obs,List<JsonNode>changes,List<JsonNode>coverage){long id=num(s.get("id"));String time=now(),expires=purpose.equals("PREPARE")?Instant.parse(time).plusSeconds(900).toString():null;long sid=insert(jdbc,"INSERT INTO stocktake_snapshot(session_id,snapshot_kind,source_revision,schema_version,snapshot_json,digest,creator_id,created_at,expires_at) VALUES (?,?,?,1,'{}',?,?,?,?)",id,purpose.equals("BASELINE")?"BASELINE":"REVIEW",s.get("revision"),hash(obj()),a.id,local(time),local(expires));List<Long>diffIds=new ArrayList<>();for(JsonNode d:projection.differences(graph,obs,coverage,changes.isEmpty()))diffIds.add(insert(jdbc,"INSERT INTO stocktake_difference(session_id,review_snapshot_id,difference_key,type,copy_id,raw_identity,evidence_json,creator_id,created_at) VALUES (?,?,?,?,?,?,?,?,?)",id,sid,bytes(d.path("differenceKey").asText()),d.path("type").asText(),d.path("copyId").isNull()?null:d.path("copyId").asLong(),d.path("rawBarcode").isNull()?null:bytes(d.path("rawBarcode").asText()),write(d.path("evidence")),a.id,local(time)));ObjectNode review=obj("snapshotId",sid,"snapshotKind",purpose.equals("BASELINE")?"BASELINE":"REVIEW","purpose",purpose,"sourceRevision",s.get("revision"),"schemaVersion",1,"createdAt",time,"expiresAt",expires,"completionKind",completion,"graph",graph,"observationDigest",hash(obs),"coverage",coverage,"changes",changes,"differenceIds",diffIds);review.put("digest",hash(review));jdbc.update("UPDATE stocktake_snapshot SET snapshot_json=?,digest=? WHERE id=?",write(review),review.path("digest").asText(),sid);return review;}
    JsonNode lockedGraph(Map<String,Object>s,List<JsonNode>obs){JsonNode first=graph(s,obs,List.of());for(Long id:longs(first.path("bookIds")))lock("book",id);JsonNode afterBook=graph(s,obs,List.of());if(!first.path("bookIds").equals(afterBook.path("bookIds"))||!first.path("recordIds").equals(afterBook.path("recordIds")))throw fail("STOCKTAKE_CHANGED");for(Long id:longs(first.path("recordIds")))lock("borrow_record",id);for(Long id:longs(first.path("copyIds")))lock("book_copy",id);SortedSet<Long>shelves=new TreeSet<>(),storeys=new TreeSet<>();for(JsonNode r:first.path("addresses")){JsonNode ad=r.path("address");if(ad.path("bookshelfId").isIntegralNumber())shelves.add(ad.path("bookshelfId").asLong());if(ad.path("storeyId").isIntegralNumber())storeys.add(ad.path("storeyId").asLong());}for(Long id:shelves)lock("bookshelf",id);for(Long id:storeys)lock("bookshelf_storey",id);for(Long id:longs(first.path("addressIds")))lock("book_location",id);JsonNode current=graph(s,obs,List.of());for(String field:List.of("bookIds","recordIds","copyIds","addressIds"))if(!first.path(field).equals(current.path(field)))throw fail("STOCKTAKE_CHANGED");return current;}
    public JsonNode recheck(long id,JsonNode raw,Actor a){return run("RECHECK",id,raw,a,true,(op,s,in)->{List<JsonNode>obs=projection.observations(id);JsonNode g=lockedGraph(s,obs);Map<String,JsonNode>changes=new HashMap<>();for(JsonNode c:projection.changes(id,num(s.get("revision")),g,projection.references(baseline(s),obs)))changes.put(c.path("entityKey").asText(),c);List<JsonNode>accepted=new ArrayList<>();for(JsonNode i:in.path("items")){String key=i.path("entityKey").asText();JsonNode c=changes.get(key);if(c==null||!c.path("changeToken").equals(i.path("changeToken"))||!c.path("expectedSignatureDigest").equals(i.path("expectedSignatureDigest")))throw fail("RECHECK_STALE");String decision=i.path("decision").asText();if(!List.of("COPY","LOAN").contains(c.path("category").asText())&&!decision.equals("CONFIRM_EXPLANATION"))invalid();if(decision.equals("LEGITIMATE_LOAN")&&(!c.path("copyId").isIntegralNumber()||!projection.healthyLoan(g,c.path("copyId").asLong())))throw fail("RECHECK_STALE");accepted.add(obj("entityKey",key,"signatureDigest",c.path("expectedSignatureDigest"),"decision",decision,"evidence",i.path("evidence")));}long oid=fact(id,"RECHECK",obj("items",accepted),a,in.path("reason").asText());revision(id,s);return result(session(s),List.of(oid),null,null,null);});}
    public JsonNode confirm(long id,JsonNode raw,Actor a){return run("CONFIRM",id,raw,a,true,(op,s,in)->{JsonNode review=projection.snapshot(id,in.path("reviewSnapshotId").asLong());if(!review.path("purpose").asText().equals("PREPARE")||!review.path("digest").equals(in.path("previewDigest"))||review.path("sourceRevision").asLong()!=num(s.get("revision")))throw fail("STOCKTAKE_CHANGED");if(!Instant.parse(review.path("expiresAt").asText()).isAfter(Instant.now()))throw fail("PREVIEW_EXPIRED");List<JsonNode>obs=projection.observations(id);JsonNode g=lockedGraph(s,obs);if(!g.path("fingerprint").equals(review.path("graph").path("fingerprint"))||!hash(obs).equals(review.path("observationDigest").asText()))throw fail("STOCKTAKE_CHANGED");if(!projection.changes(id,num(s.get("revision")),g,projection.references(baseline(s),obs)).isEmpty())throw fail("STOCKTAKE_CHANGED");if(review.path("completionKind").asText().equals("COMPLETE_SCOPE"))for(JsonNode c:review.path("coverage"))if(!c.path("status").asText().equals("COMPLETE"))throw fail("COVERAGE_INCOMPLETE");String time=now();JsonNode receipt=obj("schemaVersion",1,"sessionId",id,"reviewSnapshotId",review.path("snapshotId"),"completionKind",review.path("completionKind"),"scopeDigest",hash(g.path("scope")),"baselineMembershipDigest",hash(g.path("baselineMembership")),"currentMembershipDigest",hash(g.path("currentMembership")),"observationDigest",review.path("observationDigest"),"finalDifferenceIds",review.path("differenceIds"),"coverage",review.path("coverage"),"actorId",a.id,"confirmedAt",time,"graphFingerprint",g.path("fingerprint"));jdbc.update("UPDATE stocktake_session SET state='FINALIZED',final_snapshot_id=?,final_receipt_json=?,confirmed_at=? WHERE id=?",review.path("snapshotId").asLong(),write(receipt),local(time),id);return result(session(sessionRow(id,false)),List.of(),null,receipt,null);});}
    public JsonNode cancel(long id,JsonNode raw,Actor a){return run("CANCEL",id,raw,a,false,(op,s,in)->{jdbc.update("UPDATE stocktake_session SET state='CANCELLED' WHERE id=?",id);return result(session(sessionRow(id,false)),List.of(),null,null,null);});}
    public JsonNode snapshot(long id,long snapshot,Actor a){a.role();return transaction(false,true,()->{access(sessionRow(id,false),a,false);return projection.snapshot(id,snapshot);});}
    public JsonNode observations(long id,int page,int size,Long copy,String kind,Actor a){a.role();if(copy!=null&&copy<=0||kind!=null&&!List.of("SCAN","CORRECTION","VOID","COVERAGE","RECHECK").contains(kind))invalid();return transaction(false,true,()->{access(sessionRow(id,false),a,false);return slice(projection.observations(id).stream().filter(o->(copy==null||o.path("resolvedCopyIdAtScan").asLong(-1)==copy)&&(kind==null||o.path("kind").asText().equals(kind))).toList(),page,size);});}
    JsonNode difference(Map<String,Object>r){String raw=StocktakeSupport.raw(r.get("raw_identity"));return obj("differenceId",r.get("id"),"sessionId",r.get("session_id"),"reviewSnapshotId",r.get("review_snapshot_id"),"differenceKey",StocktakeSupport.raw(r.get("difference_key")),"type",r.get("type"),"copyId",r.get("copy_id"),"rawBarcode",raw,"rawBarcodeBase64",raw==null?null:b64(raw),"evidence",read((String)r.get("evidence_json")),"createdAt",time(r.get("created_at")));}
    JsonNode selectedReview(Map<String,Object>s,Long requested,boolean prepare){long id=num(s.get("id"));if(requested!=null)return projection.snapshot(id,requested);if(s.get("final_snapshot_id")!=null)return projection.snapshot(id,num(s.get("final_snapshot_id")));if(!prepare)return projection.latest(id);List<String>rows=jdbc.queryForList("SELECT snapshot_json FROM stocktake_snapshot WHERE session_id=? ORDER BY id DESC",String.class,id);for(String r:rows){JsonNode n=read(r);if(n.path("purpose").asText().equals("PREPARE"))return n;}return NullNode.instance;}
    public JsonNode differences(long id,Long review,String type,Long copy,int page,int size,Actor a){a.role();if(copy!=null&&copy<=0||review!=null&&review<=0||type!=null&&type.length()>48)invalid();return transaction(false,true,()->{var s=sessionRow(id,false);access(s,a,false);JsonNode snap=selectedReview(s,review,true);List<Object>args=new ArrayList<>(List.of(id,snap.path("snapshotId").asLong()));String w=" WHERE session_id=? AND review_snapshot_id=?";if(type!=null){w+=" AND type=?";args.add(type);}if(copy!=null){w+=" AND copy_id=?";args.add(copy);}long total=jdbc.queryForObject("SELECT COUNT(*) FROM stocktake_difference"+w,Long.class,args.toArray());int p=Math.max(1,page),n=Math.max(1,Math.min(100,size));args.add(n);args.add(((long)p-1)*n);return page(jdbc.queryForList("SELECT * FROM stocktake_difference"+w+" ORDER BY id LIMIT ? OFFSET ?",args.toArray()).stream().map(this::difference).toList(),total,p,n);});}
    public JsonNode changes(long id,Long review,String category,Long copy,int page,int size,Actor a){a.role();if(copy!=null&&copy<=0||review!=null&&review<=0||category!=null&&!List.of("COPY","LOAN","ADDRESS","BOOK","SCOPE","BARCODE").contains(category))invalid();return transaction(false,true,()->{var s=sessionRow(id,false);access(s,a,false);List<JsonNode>rows=new ArrayList<>();for(JsonNode c:selectedReview(s,review,false).path("changes"))if((category==null||c.path("category").asText().equals(category))&&(copy==null||c.path("copyId").asLong(-1)==copy))rows.add(c);return slice(rows,page,size);});}
}
